final class BinarySearcher {
    private BinarySearcher() {
    }

    static SearchResult search(int[] sortedArray, int target) {
        validateInput(sortedArray);

        int low = 0;
        int high = sortedArray.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (sortedArray[mid] == target) {
                return SearchResult.foundAt(mid);
            }

            if (sortedArray[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return SearchResult.notFound();
    }

    private static void validateInput(int[] sortedArray) {
        if (sortedArray == null) {
            throw new IllegalArgumentException("sortedArray must not be null");
        }
    }
}

final class SearchResult {
    static final int NOT_FOUND_INDEX = -1;

    private static final SearchResult NOT_FOUND = new SearchResult(NOT_FOUND_INDEX);

    private final int index;

    private SearchResult(int index) {
        this.index = index;
    }

    static SearchResult foundAt(int index) {
        if (index < 0) {
            throw new IllegalArgumentException("index must be non-negative");
        }

        return new SearchResult(index);
    }

    static SearchResult notFound() {
        return NOT_FOUND;
    }

    boolean isFound() {
        return index != NOT_FOUND_INDEX;
    }

    int index() {
        return index;
    }
}

final class SearchResultFormatter {
    private static final String FOUND_MESSAGE = "Element is present at index ";
    private static final String NOT_FOUND_MESSAGE = "Element is not present in array";

    private SearchResultFormatter() {
    }

    static String format(SearchResult result) {
        if (result == null) {
            throw new IllegalArgumentException("result must not be null");
        }

        if (!result.isFound()) {
            return NOT_FOUND_MESSAGE;
        }

        return FOUND_MESSAGE + result.index();
    }
}

final class BinarySearchDemo {
    private BinarySearchDemo() {
    }

    static void run() {
        int[] sortedArray = { 2, 3, 4, 10, 40 };
        int target = 10;
        SearchResult result = BinarySearcher.search(sortedArray, target);

        System.out.println(SearchResultFormatter.format(result));
    }
}
